/* Public Instagram material, presented as a dated fan archive. No live account data. */
(function(root){
'use strict';
const D=root.InstagramArchiveData;
let profile='seulgi',tab='own',postId='',slide=0;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=p=>p.date.replaceAll('-','.');
const find=id=>D.posts.find(p=>p.id===id);
const list=()=>D.posts.filter(p=>tab==='own'?p.owner===profile:p.related.includes(profile)).sort((a,b)=>(b.date+(b.time||'')).localeCompare(a.date+(a.time||'')));
function top(title,back=false){return `<header class="ia-head"><button ${back?'data-ig-back':'data-nav="forum"'} aria-label="${back?'返回主页':'返回论坛'}">‹</button><strong>${title}</strong><button data-nav="phonehome" aria-label="返回我的手机">⌂</button></header>`}
function tile(p){return `<button class="ia-tile ${p.images.length?'':'ia-text-tile'}" data-ig-post="${p.id}" aria-label="打开 ${date(p)} ${esc(p.title)}">${p.images.length?`<img src="${p.images[0].src}" alt="${esc(p.images[0].alt)}" loading="lazy" width="240" height="240">`:`<span class="ia-quote">“</span><strong>${esc(p.title)}</strong>`}<span class="ia-tile-kind">${p.images.length>1?'▣ '+p.images.length:p.kind.includes('存档')?'▤':'▧'}</span><span class="ia-tile-date">${date(p)}</span></button>`}
function html(state){return `<section class="nf-app ia-app">${postId?post(state):home(state)}</section>`}
function home(state){const P=D.profiles[profile],records=list(),owned=D.posts.filter(p=>p.owner===profile).length;return `${top('Instagram')}<div class="ia-account-switch" aria-label="选择个人主页">${Object.entries(D.profiles).map(([k,p])=>`<button data-ig-profile="${k}" class="${profile===k?'active':''}"><span style="--avatar:${p.color}">${p.initial}</span><b>${p.handle}</b></button>`).join('')}</div><div class="nf-scroll ia-profile-scroll"><section class="ia-profile"><div class="ia-profile-main"><div class="ia-avatar" style="--avatar:${P.color}">${P.initial}</div><div><h1>${P.handle}</h1><strong>${P.name}</strong><p>公开内容存档</p></div></div><p class="ia-bio">翻一翻公开留下的日常。<br><span>${owned} 组本人更新 · ${D.posts.filter(p=>p.related.includes(profile)).length} 组相关记录</span></p><div class="ia-profile-actions"><a href="${P.url}" target="_blank" rel="noopener noreferrer">查看 INS 主页 ↗</a><button data-nav="notebook">我的收藏 ${state.igSaved.length?'· '+state.igSaved.length:''}</button></div></section><div class="ia-story-strip"><button data-ig-post="sg-meal-260916"><span>🍚</span><small>日本活动期</small></button><button data-ig-post="sg-250623"><span>♫</span><small>BALANCE</small></button><button data-ig-post="by-250330"><span>▧</span><small>镜头里的她</small></button></div><nav class="ia-tabs" aria-label="内容范围"><button data-ig-tab="related" class="${tab==='related'?'active':''}">▦ 同框与提及</button><button data-ig-tab="own" class="${tab==='own'?'active':''}">▤ 本人发布</button></nav><div class="ia-grid">${records.map(tile).join('')}</div><div class="ia-archive-footer"><p>按原更新日期排列 · 已收录 ${records.length} 组</p><small>本页为公开资料摘录，并非实时完整主页。图片与文案保留出处；未核实的原配文不补写。</small><button data-ig-fiction>查看剧情中的动态 →</button></div></div><nav class="ia-bottom"><button data-nav="forum">⌂<span>回到论坛</span></button><button data-ig-profile="seulgi">S<span>Seulgi</span></button><button data-ig-profile="irene">I<span>Irene</span></button><button data-nav="notebook">▤<span>我的手记</span></button></nav>`}
function post(state){const p=find(postId)||D.posts[0],P=D.profiles[p.owner],saved=state.igSaved.includes(p.id),img=p.images[slide];return `${top('帖子',true)}<div class="nf-scroll ia-post-scroll"><header class="ia-post-byline"><button class="ia-small-avatar" style="--avatar:${P.color}" data-ig-profile="${p.owner}">${P.initial}</button><div><button data-ig-profile="${p.owner}">${esc(p.account)}</button><small>${date(p)}${p.time?' · '+p.time+' KST':''}</small></div><span>${p.kind}</span></header>${img?`<div class="ia-canvas" tabindex="0" aria-label="图片 ${slide+1}，共 ${p.images.length} 张"><img src="${img.src}" alt="${esc(img.alt)}" decoding="async">${p.images.length>1?`<span class="ia-photo-counter">${slide+1} / ${p.images.length}</span>`:''}</div>${p.images.length>1?`<div class="ia-carousel-controls"><button data-ig-step="-1" ${slide===0?'disabled':''} aria-label="上一张">‹</button><span>滑动图片，或点击两侧翻页</span><button data-ig-step="1" ${slide===p.images.length-1?'disabled':''} aria-label="下一张">›</button></div>`:''}`:`<div class="ia-text-photo"><span>“</span><h1>${esc(p.title)}</h1><small>${esc(p.imageNote||'文字索引')}</small></div>`}<article class="ia-post-copy"><div class="ia-post-actions"><button data-ig-save="${p.id}" class="${saved?'saved':''}" aria-pressed="${saved}">${saved?'★ 已收藏':'☆ 收藏到手记'}</button><button data-ig-profile="${p.owner==='irene'?'seulgi':'irene'}">去对方主页 →</button></div>${p.caption?`<p class="ia-caption"><strong>${esc(p.account)}</strong> ${esc(p.caption)}</p><p class="ia-translation">译：${esc(p.translation)}</p>`:`<p class="ia-caption"><strong>${esc(p.account)}</strong> ${esc(p.title)}</p>`}<p class="ia-summary">${esc(p.summary)}</p>${p.comment?`<aside class="ia-real-comment"><span>存档记录的公开留言</span><p><strong>${esc(p.comment.account)}</strong> ${esc(p.comment.text)}</p><small>${esc(p.comment.translation)}</small><button data-ig-profile="seulgi">查看她的主页 →</button></aside>`:''}<details class="ia-source"><summary>来源与日期</summary><p>更新日期：${date(p)}${p.time?' · '+p.time+' KST':''}。以公开存档记录为依据，不使用转载页面的上传日期。</p><div>${p.url?`<a href="${p.url}" target="_blank" rel="noopener noreferrer">打开原帖 ↗</a>`:''}<a href="${p.archive}" target="_blank" rel="noopener noreferrer">查看公开存档 ↗</a></div><p>图片属于原作者。中文为阅读译文；这条资料不对私人关系作判断。</p></details><p class="ia-date">${date(p)} · ${p.images.length?p.images.length+' 张存档图片':'文字索引'}</p><button class="ia-open-notebook" data-nav="notebook">打开我的手记 →</button></article></div>`}
function selectPost(id){if(!find(id))return false;postId=id;profile=find(id).owner;slide=0;return true}
function savedCards(state){const records=state.igSaved.map(find).filter(Boolean);return records.length?`<section class="ia-notebook"><small>公开 INS 资料</small>${records.map(p=>`<button class="nf-note-record" data-ig-open="${p.id}"><span>@${p.account} · ${date(p)}</span><strong>${esc(p.title)}</strong><p>${esc(p.summary)}</p></button>`).join('')}</section>`:''}
function bind(ctx){const s=ctx.screen,redraw=ctx.render;
 s.querySelectorAll('[data-ig-profile]').forEach(b=>b.onclick=()=>{profile=b.dataset.igProfile;postId='';tab='own';slide=0;redraw()});
 s.querySelectorAll('[data-ig-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.igTab;redraw()});
 s.querySelectorAll('[data-ig-post]').forEach(b=>b.onclick=()=>{selectPost(b.dataset.igPost);redraw()});
 s.querySelectorAll('[data-ig-back]').forEach(b=>b.onclick=()=>{postId='';slide=0;redraw()});
 s.querySelectorAll('[data-ig-save]').forEach(b=>b.onclick=()=>ctx.onSave(b.dataset.igSave));
 s.querySelectorAll('[data-ig-fiction]').forEach(b=>b.onclick=ctx.fiction);
 function step(n){const p=find(postId);if(!p)return;const next=Math.max(0,Math.min(p.images.length-1,slide+n));if(next===slide)return;const y=s.querySelector('.nf-scroll')?.scrollTop||0;slide=next;redraw();const sc=s.querySelector('.nf-scroll');if(sc)sc.scrollTop=y}
 s.querySelectorAll('[data-ig-step]').forEach(b=>b.onclick=()=>step(Number(b.dataset.igStep)));
 const canvas=s.querySelector('.ia-canvas');if(canvas){let x=0;canvas.addEventListener('touchstart',e=>{x=e.changedTouches[0].clientX},{passive:true});canvas.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-x;if(Math.abs(dx)>50)step(dx<0?1:-1)},{passive:true});canvas.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();step(e.key==='ArrowRight'?1:-1)}}}
}
root.InstagramArchive={html,bind,selectPost,savedCards,posts:()=>D.posts};
})(window);
